[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ScreenVault — UI & UX Design Inspiration for Mobile & Web Apps</title>
<meta name="description" content="Save hours of UI & UX research with a library of 400,000+ fully searchable mobile & web app screenshots.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #FFFFFF;
  --color-surface: #F5F5F5;
  --color-surface-alt: #FAFAFA;
  --color-text: #141414;
  --color-text-secondary: #6B7280;
  --color-text-muted: #9CA3AF;
  --color-accent: #6C5CE7;
  --color-accent-hover: #5A4BD1;
  --color-accent-light: #EDE9FE;
  --color-border: #E5E7EB;
  --color-border-light: #F3F4F6;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.08);
  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
img { max-width: 100%; display: block; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
  .marquee-track { animation: none !important; }
}

/* ==================== ANNOUNCEMENT BAR ==================== */
.announcement-bar {
  background: var(--color-text);
  color: #fff;
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.announcement-bar span { color: var(--color-accent-light); }

/* ==================== HEADER / NAV ==================== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-light);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-icon svg { width: 16px; height: 16px; }
.nav { display: flex; align-items: center; gap: 32px; }
.nav a {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.nav a:hover { color: var(--color-text); }

/* ==================== HERO ==================== */
.hero {
  padding: 80px 0 64px;
  text-align: center;
}
.hero h1 {
  font-size: clamp(36px, 5vw, 64px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 20px;
  color: var(--color-text);
}
.hero .subtitle {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--color-text-secondary);
  max-width: 560px;
  margin: 0 auto 40px;
  line-height: 1.6;
}
.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  background: var(--color-accent);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition);
}
.btn-primary:hover { background: var(--color-accent-hover); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(108,92,231,0.3); }
.btn-primary:active { transform: translateY(0); }
.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  background: transparent;
  color: var(--color-text);
  font-size: 15px;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: 1.5px solid var(--color-border);
  transition: all var(--transition);
}
.btn-secondary:hover { border-color: var(--color-text-secondary); background: var(--color-surface); }

/* ==================== TRUSTED BY ==================== */
.trusted-by {
  padding: 48px 0 64px;
  text-align: center;
}
.trusted-by p {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 32px;
}
.logo-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.5;
}
.logo-row .brand-logo {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.01em;
  white-space: nowrap;
}

/* ==================== STATS ==================== */
.stats-section {
  padding: 80px 0;
  background: var(--color-surface);
}
.stats-label {
  text-align: center;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 48px;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item .stat-number {
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
  color: var(--color-text);
  font-variant-numeric: tabular-nums;
}
.stat-item .stat-label {
  font-size: 16px;
  font-weight: 500;
  color: var(--color-text-secondary);
  margin-top: 8px;
}

/* ==================== FEATURES: SEARCH ==================== */
.features-search {
  padding: 100px 0;
}
.section-header {
  text-align: center;
  margin-bottom: 48px;
}
.section-header h2 {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 17px;
  color: var(--color-text-secondary);
  max-width: 520px;
  margin: 0 auto;
}

.search-tabs {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-bottom: 24px;
  background: var(--color-surface);
  border-radius: var(--radius-full);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.search-tab {
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition);
  white-space: nowrap;
}
.search-tab:hover { color: var(--color-text); }
.search-tab.active {
  background: #fff;
  color: var(--color-text);
  box-shadow: var(--shadow-sm);
}

.filter-pills {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 40px;
  padding: 0 16px;
}
.filter-pill {
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  transition: all var(--transition);
  white-space: nowrap;
}
.filter-pill:hover { border-color: var(--color-accent); color: var(--color-accent); }
.filter-pill.active {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

.screenshot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.screenshot-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  aspect-ratio: 9/16;
  overflow: hidden;
  position: relative;
  transition: transform var(--transition), box-shadow var(--transition);
}
.screenshot-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.screenshot-card-inner {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 16px;
  justify-content: space-between;
}
.card-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.card-status-bar {
  height: 6px;
  width: 60%;
  background: var(--color-border);
  border-radius: 3px;
}
.card-dots { display: flex; gap: 3px; }
.card-dots span { width: 4px; height: 4px; background: var(--color-text-muted); border-radius: 50%; }
.card-content-lines { display: flex; flex-direction: column; gap: 8px; flex: 1; justify-content: center; }
.card-line {
  height: 8px;
  background: var(--color-border);
  border-radius: 4px;
}
.card-line.short { width: 60%; }
.card-line.medium { width: 80%; }
.card-bottom-bar {
  display: flex;
  gap: 8px;
}
.card-btn-placeholder {
  flex: 1;
  height: 28px;
  background: var(--color-border);
  border-radius: var(--radius-sm);
}
.card-btn-placeholder.accent { background: var(--color-accent-light); }

.screenshot-card[data-color="blue"] { background: #EEF2FF; }
.screenshot-card[data-color="blue"] .card-line, .screenshot-card[data-color="blue"] .card-status-bar, .screenshot-card[data-color="blue"] .card-btn-placeholder { background: #C7D2FE; }
.screenshot-card[data-color="blue"] .card-btn-placeholder.accent { background: #818CF8; }

.screenshot-card[data-color="green"] { background: #F0FDF4; }
.screenshot-card[data-color="green"] .card-line, .screenshot-card[data-color="green"] .card-status-bar, .screenshot-card[data-color="green"] .card-btn-placeholder { background: #BBF7D0; }
.screenshot-card[data-color="green"] .card-btn-placeholder.accent { background: #4ADE80; }

.screenshot-card[data-color="rose"] { background: #FFF1F2; }
.screenshot-card[data-color="rose"] .card-line, .screenshot-card[data-color="rose"] .card-status-bar, .screenshot-card[data-color="rose"] .card-btn-placeholder { background: #FECDD3; }
.screenshot-card[data-color="rose"] .card-btn-placeholder.accent { background: #FB7185; }

.screenshot-card[data-color="amber"] { background: #FFFBEB; }
.screenshot-card[data-color="amber"] .card-line, .screenshot-card[data-color="amber"] .card-status-bar, .screenshot-card[data-color="amber"] .card-btn-placeholder { background: #FDE68A; }
.screenshot-card[data-color="amber"] .card-btn-placeholder.accent { background: #FBBF24; }

.screenshot-card[data-color="violet"] { background: #F5F3FF; }
.screenshot-card[data-color="violet"] .card-line, .screenshot-card[data-color="violet"] .card-status-bar, .screenshot-card[data-color="violet"] .card-btn-placeholder { background: #DDD6FE; }
.screenshot-card[data-color="violet"] .card-btn-placeholder.accent { background: #A78BFA; }

.screenshot-card[data-color="sky"] { background: #F0F9FF; }
.screenshot-card[data-color="sky"] .card-line, .screenshot-card[data-color="sky"] .card-status-bar, .screenshot-card[data-color="sky"] .card-btn-placeholder { background: #BAE6FD; }
.screenshot-card[data-color="sky"] .card-btn-placeholder.accent { background: #38BDF8; }

.screenshot-card[data-color="teal"] { background: #F0FDFA; }
.screenshot-card[data-color="teal"] .card-line, .screenshot-card[data-color="teal"] .card-status-bar, .screenshot-card[data-color="teal"] .card-btn-placeholder { background: #99F6E4; }
.screenshot-card[data-color="teal"] .card-btn-placeholder.accent { background: #2DD4BF; }

.screenshot-card[data-color="slate"] { background: #F8FAFC; }
.screenshot-card[data-color="slate"] .card-line, .screenshot-card[data-color="slate"] .card-status-bar, .screenshot-card[data-color="slate"] .card-btn-placeholder { background: #CBD5E1; }
.screenshot-card[data-color="slate"] .card-btn-placeholder.accent { background: #94A3B8; }

/* ==================== FEATURES: FLOWS ==================== */
.features-flows {
  padding: 100px 0;
  background: var(--color-surface);
}
.flows-toggle {
  display: flex;
  gap: 4px;
  justify-content: center;
  margin-bottom: 40px;
  background: #fff;
  border-radius: var(--radius-full);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.flow-toggle-btn {
  padding: 10px 24px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}
.flow-toggle-btn:hover { color: var(--color-text); }
.flow-toggle-btn.active {
  background: var(--color-accent);
  color: #fff;
}
.flow-content-area {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 48px;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-light);
}
.flow-view { display: none; width: 100%; }
.flow-view.active { display: block; }
.flow-video-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.flow-video-card {
  aspect-ratio: 9/16;
  background: linear-gradient(135deg, var(--color-accent-light) 0%, #F0EAFF 100%);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  position: relative;
  overflow: hidden;
}
.play-icon {
  width: 48px;
  height: 48px;
  background: rgba(108,92,231,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.play-icon svg { width: 20px; height: 20px; color: var(--color-accent); }
.flow-video-label { font-size: 13px; font-weight: 500; color: var(--color-accent); }
.flow-prototype-view {
  display: flex;
  gap: 16px;
  align-items: center;
  overflow-x: auto;
  padding-bottom: 8px;
}
.prototype-step {
  flex: 0 0 180px;
  aspect-ratio: 9/16;
  background: var(--color-surface);
  border-radius: var(--radius-md);
  border: 2px solid var(--color-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: border-color var(--transition);
  position: relative;
}
.prototype-step:hover { border-color: var(--color-accent); }
.prototype-step .step-num {
  width: 28px;
  height: 28px;
  background: var(--color-accent-light);
  color: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
}
.prototype-step .step-label { font-size: 12px; color: var(--color-text-secondary); font-weight: 500; }
.prototype-arrow {
  flex: 0 0 auto;
  color: var(--color-text-muted);
}
.prototype-arrow svg { width: 20px; height: 20px; }
.hotspot-dot {
  position: absolute;
  width: 12px;
  height: 12px;
  background: var(--color-accent);
  border-radius: 50%;
  bottom: 24px;
  animation: pulse-dot 2s ease-in-out infinite;
}
@keyframes pulse-dot {
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.3); }
}

/* ==================== FEATURES: TOOLS ==================== */
.features-tools {
  padding: 100px 0;
}
.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.tool-card {
  background: var(--color-surface-alt);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.tool-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); border-color: var(--color-border); }
.tool-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.tool-icon svg { width: 24px; height: 24px; color: var(--color-accent); }
.tool-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}
.tool-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ==================== TESTIMONIALS ==================== */
.testimonials-section {
  padding: 100px 0;
  background: var(--color-surface);
  overflow: hidden;
}
.marquee {
  position: relative;
  overflow: hidden;
  margin-bottom: 20px;
}
.marquee:last-child { margin-bottom: 0; }
.marquee-track {
  display: flex;
  gap: 20px;
  width: max-content;
}
.marquee-track.scroll-left { animation: marquee-left 60s linear infinite; }
.marquee-track.scroll-right { animation: marquee-right 60s linear infinite; }

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.testimonial-card {
  flex: 0 0 380px;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--color-border-light);
}
.testimonial-text {
  font-size: 14px;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: 20px;
}
.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}
.testimonial-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
  color: var(--color-accent);
}
.testimonial-name { font-size: 14px; font-weight: 600; }
.testimonial-role { font-size: 13px; color: var(--color-text-muted); }

/* ==================== CTA SECTION ==================== */
.cta-section {
  padding: 100px 0 0;
  text-align: center;
}
.cta-section h2 {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-bottom: 16px;
}
.cta-section .cta-desc {
  font-size: 17px;
  color: var(--color-text-secondary);
  max-width: 520px;
  margin: 0 auto 40px;
}
.cta-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 80px;
}
.brand-marquee-area {
  padding: 48px 0;
  overflow: hidden;
  background: var(--color-surface);
}
.brand-marquee {
  position: relative;
  overflow: hidden;
  margin-bottom: 16px;
}
.brand-marquee:last-child { margin-bottom: 0; }
.brand-marquee-track {
  display: flex;
  gap: 24px;
  width: max-content;
}
.brand-marquee-track.scroll-left { animation: marquee-left 40s linear infinite; }
.brand-marquee-track.scroll-right { animation: marquee-right 40s linear infinite; }
.app-icon-item {
  flex: 0 0 auto;
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
}

/* ==================== FOOTER ==================== */
.footer {
  background: var(--color-text);
  color: #fff;
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .footer-tagline {
  font-size: 14px;
  color: rgba(255,255,255,0.6);
  line-height: 1.6;
  max-width: 280px;
  margin-top: 16px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 20px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 12px; }
.footer-col a {
  font-size: 14px;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
