<script>
(function() {
  'use strict';

  // ==================== ANIMATED STAT COUNTERS ====================
  const counters = document.querySelectorAll('.stat-number[data-target]');
  let countersAnimated = false;

  function formatNumber(num) {
    return num.toLocaleString('en-US');
  }

  function animateCounter(el, target, duration) {
    const start = 0;
    const startTime = performance.now();

    function easeOutQuart(t) {
      return 1 - Math.pow(1 - t, 4);
    }

    function update(currentTime) {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const easedProgress = easeOutQuart(progress);
      const current = Math.floor(start + (target - start) * easedProgress);
      el.textContent = formatNumber(current);
      if (progress < 1) {
        requestAnimationFrame(update);
      } else {
        el.textContent = formatNumber(target);
      }
    }
    requestAnimationFrame(update);
  }

  const statsObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting && !countersAnimated) {
        countersAnimated = true;
        counters.forEach(function(counter, index) {
          const target = parseInt(counter.getAttribute('data-target'), 10);
          setTimeout(function() {
            animateCounter(counter, target, 2000);
          }, index * 200);
        });
        statsObserver.disconnect();
      }
    });
  }, { threshold: 0.3 });

  const statsSection = document.querySelector('.stats-section');
  if (statsSection) statsObserver.observe(statsSection);

  // ==================== SEARCH TABS ====================
  const searchTabs = document.querySelectorAll('.search-tab');
  const screenshotGrid = document.getElementById('screenshotGrid');

  searchTabs.forEach(function(tab) {
    tab.addEventListener('click', function() {
      searchTabs.forEach(function(t) {
        t.classList.remove('active');
        t.setAttribute('aria-selected', 'false');
      });
      this.classList.add('active');
      this.setAttribute('aria-selected', 'true');
      generateGrid(this.getAttribute('data-tab'), getActiveFilter());
    });
  });

  // ==================== FILTER PILLS ====================
  const filterPills = document.querySelectorAll('.filter-pill');

  filterPills.forEach(function(pill) {
    pill.addEventListener('click', function() {
      filterPills.forEach(function(p) {
        p.classList.remove('active');
        p.setAttribute('aria-selected', 'false');
      });
      this.classList.add('active');
      this.setAttribute('aria-selected', 'true');
      generateGrid(getActiveTab(), this.textContent.trim());
    });
  });

  function getActiveTab() {
    var active = document.querySelector('.search-tab.active');
    return active ? active.getAttribute('data-tab') : 'screens';
  }

  function getActiveFilter() {
    var active = document.querySelector('.filter-pill.active');
    return active ? active.textContent.trim() : 'Profile';
  }

  // ==================== SCREENSHOT GRID GENERATION ====================
  var colorSchemes = ['blue', 'green', 'rose', 'amber', 'violet', 'sky', 'teal', 'slate'];

  function seededRandom(seed) {
    var x = Math.sin(seed) * 10000;
    return x - Math.floor(x);
  }

  function generateGrid(tab, filter) {
    var grid = screenshotGrid;
    grid.innerHTML = '';
    var seed = 0;
    for (var i = 0; i < tab.length; i++) seed += tab.charCodeAt(i);
    for (var i = 0; i < filter.length; i++) seed += filter.charCodeAt(i);

    var count = 8;
    for (var i = 0; i < count; i++) {
      var color = colorSchemes[Math.floor(seededRandom(seed + i * 7) * colorSchemes.length)];
      var card = document.createElement('div');
      card.className = 'screenshot-card';
      card.setAttribute('data-color', color);

      var lineWidths = ['', 'short', 'medium'];
      var lines = '';
      var numLines = 3 + Math.floor(seededRandom(seed + i * 13) * 3);
      for (var j = 0; j < numLines; j++) {
        var widthClass = lineWidths[Math.floor(seededRandom(seed + i * 17 + j * 3) * lineWidths.length)];
        lines += '<div class="card-line ' + widthClass + '"></div>';
      }

      var hasAccent = seededRandom(seed + i * 23) > 0.4;
      card.innerHTML =
        '<div class="screenshot-card-inner">' +
          '<div class="card-top-bar">' +
            '<div class="card-status-bar"></div>' +
            '<div class="card-dots"><span></span><span></span><span></span></div>' +
          '</div>' +
          '<div class="card-content-lines">' + lines + '</div>' +
          '<div class="card-bottom-bar">' +
            '<div class="card-btn-placeholder"></div>' +
            (hasAccent ? '<div class="card-btn-placeholder accent"></div>' : '') +
          '</div>' +
        '</div>';

      card.style.opacity = '0';
      card.style.transform = 'translateY(12px)';
      grid.appendChild(card);

      (function(c, delay) {
        setTimeout(function() {
          c.style.transition = 'opacity 300ms ease, transform 300ms ease';
          c.style.opacity = '1';
          c.style.transform = 'translateY(0)';
        }, delay);
      })(card, i * 50);
    }
  }

  generateGrid('screens', 'Profile');

  // ==================== FLOWS TOGGLE ====================
  var flowBtns = document.querySelectorAll('.flow-toggle-btn');
  var flowViews = document.querySelectorAll('.flow-view');

  flowBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      flowBtns.forEach(function(b) {
        b.classList.remove('active');
        b.setAttribute('aria-selected', 'false');
      });
      this.classList.add('active');
      this.setAttribute('aria-selected', 'true');

      var target = this.getAttribute('data-flow');
      flowViews.forEach(function(view) {
        view.classList.remove('active');
      });
      document.getElementById('flow-' + target).classList.add('active');
    });
  });

  // ==================== BRAND ICON MARQUEE ====================
  var brands = [
    { name: 'Coinbase', color: '#1652F0' },
    { name: 'Wise', color: '#9FE870' },
    { name: 'Headspace', color: '#F47D31' },
    { name: 'Airbnb', color: '#FF5A5F' },
    { name: 'Uber', color: '#000000' },
    { name: 'Nike', color: '#111111' },
    { name: 'Pinterest', color: '#E60023' },
    { name: 'ChatGPT', color: '#10A37F' },
    { name: 'Shopify', color: '#96BF48' },
    { name: 'Loom', color: '#625DF5' },
    { name: 'Mailchimp', color: '#FFE01B' },
    { name: 'Twitch', color: '#9146FF' },
    { name: 'Spotify', color: '#1DB954' },
    { name: 'Apple TV', color: '#333333' },
    { name: 'Notion', color: '#000000' },
    { name: 'Dropbox', color: '#0061FF' }
  ];

  function createBrandIcons(containerId, items) {
    var container = document.getElementById(containerId);
    var all = items.concat(items);
    all.forEach(function(brand) {
      var el = document.createElement('div');
      el.className = 'app-icon-item';
      el.style.background = brand.color;
      var textColor = isLightColor(brand.color) ? '#333' : '#fff';
      el.style.color = textColor;
      el.textContent = brand.name.substring(0, 2).toUpperCase();
      el.setAttribute('title', brand.name);
      container.appendChild(el);
    });
  }

  function isLightColor(hex) {
    var r = parseInt(hex.slice(1, 3), 16);
    var g = parseInt(hex.slice(3, 5), 16);
    var b = parseInt(hex.slice(5, 7), 16);
    return (r * 299 + g * 587 + b * 114) / 1000 > 160;
  }

  var row1Brands = brands.slice(0, 8);
  var row2Brands = brands.slice(8);
  createBrandIcons('brandRow1', row1Brands);
  createBrandIcons('brandRow2', row2Brands);

})();
</script>
